<?php require_once __DIR__.'/app/bootstrap.php';$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($count){http_response_code(403);exit('অ্যাডমিন আগে থেকেই তৈরি আছে। নিরাপত্তার জন্য এই setup-admin.php ফাইলটি সার্ভার থেকে মুছে ফেলুন।');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$u=trim($_POST['username']??'');$p=$_POST['password']??'';$p2=$_POST['password2']??'';if(!preg_match('/^[a-zA-Z0-9_.-]{4,80}$/',$u))$error='ইউজারনেম ৪-৮০ অক্ষরের ইংরেজি অক্ষর/সংখ্যা হতে হবে।';elseif(strlen($p)<12)$error='পাসওয়ার্ড কমপক্ষে ১২ অক্ষরের দিন।';elseif($p!==$p2)$error='দুটি পাসওয়ার্ড মেলেনি।';else{$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);header('Location: admin/login.php');exit;}}?><!doctype html><html lang="bn"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ASPI Admin Setup</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><body class="bg-light"><div class="container py-5" style="max-width:560px"><div class="card border-0 shadow-sm p-4"><h2>ASPI Admin তৈরি করুন</h2><p>প্রথমবারের জন্য ড্যাশবোর্ডের আলাদা ইউজারনেম ও শক্তিশালী পাসওয়ার্ড সেট করুন।</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Admin username</label><input class="form-control mb-3" name="username" required minlength="4"><label class="form-label">Password (কমপক্ষে ১২ অক্ষর)</label><input class="form-control mb-3" type="password" name="password" required minlength="12"><label class="form-label">পাসওয়ার্ড আবার লিখুন</label><input class="form-control mb-3" type="password" name="password2" required minlength="12"><button class="btn btn-primary w-100">অ্যাডমিন তৈরি করুন</button></form></div></div></body></html>